use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut total_time = 0;
    let mut server_status = vec![0; input.len()];

    for line in input {
        let (arrival, duration) = line.as_array().unwrap();
        for i in 0..arrival.len() {
            server_status[i] += duration;
        }
    }

    let mut total_time = 0;
    for status in server_status {
        total_time += status;
    }

    total_time
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[[0,3],[1,2],[8,1]],\"expected\":2}");
    let result = solve(input);
    println!("{:?}", result);
}
